  s+=f'theorem {name}_evalMC9F (v : ℕ → ℚ) : devalMC9F 4 v {name} = devalMC9F 4 v {prev} * devalMC9F 4 v df{fi}MC9F := by\n rw [← {name}_eqMC9F,deval_mulMC9F]\n'
